import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { Trip } from '../../models/trip';
import { TripService } from '../../services/trip.service';

@Component({
  selector: 'app-trip-edit',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './trip-edit.component.html',
  styleUrls: ['./trip-edit.component.css']
})
export class TripEditComponent implements OnInit {
  trip: Trip = {
    code: '',
    name: '',
    length: '',
    start: '',
    resort: '',
    perPerson: '',
    image: '',
    description: ''
  };

  originalTrip: Trip | null = null;
  tripId: string | null = null;
  loading = true;
  saving = false;
  error: string | null = null;
  success: string | null = null;

  constructor(
    private tripService: TripService,
    private router: Router,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.tripId = this.route.snapshot.paramMap.get('id');
    if (this.tripId) {
      this.loadTrip();
    } else {
      this.error = 'No trip ID provided';
      this.loading = false;
    }
  }

  loadTrip(): void {
    if (!this.tripId) return;

    this.loading = true;
    this.error = null;

    this.tripService.getTrip(this.tripId).subscribe({
      next: (trip) => {
        this.trip = { ...trip };
        this.originalTrip = { ...trip };
        this.loading = false;
      },
      error: (error) => {
        console.error('Error loading trip:', error);
        this.error = 'Failed to load trip. Please try again.';
        this.loading = false;
      }
    });
  }

  onSubmit(): void {
    if (!this.validateForm() || !this.tripId) {
      return;
    }

    this.saving = true;
    this.error = null;
    this.success = null;

    this.tripService.updateTrip(this.tripId, this.trip).subscribe({
      next: (response) => {
        this.saving = false;
        this.success = 'Trip updated successfully!';

        // Update the original trip data
        this.originalTrip = { ...this.trip };

        // Redirect to trips list after a short delay
        setTimeout(() => {
          this.router.navigate(['/trips']);
        }, 1500);
      },
      error: (error) => {
        this.saving = false;
        this.error = error.message || 'Failed to update trip. Please try again.';
        console.error('Error updating trip:', error);
      }
    });
  }

  validateForm(): boolean {
    if (!this.trip.code?.trim()) {
      this.error = 'Trip code is required';
      return false;
    }
    if (!this.trip.name?.trim()) {
      this.error = 'Trip name is required';
      return false;
    }
    if (!this.trip.length?.trim()) {
      this.error = 'Trip length is required';
      return false;
    }
    if (!this.trip.start?.trim()) {
      this.error = 'Start date is required';
      return false;
    }
    if (!this.trip.resort?.trim()) {
      this.error = 'Resort information is required';
      return false;
    }
    if (!this.trip.perPerson?.trim()) {
      this.error = 'Price per person is required';
      return false;
    }
    if (!this.trip.image?.trim()) {
      this.error = 'Image URL is required';
      return false;
    }
    if (!this.trip.description?.trim()) {
      this.error = 'Description is required';
      return false;
    }

    this.error = null;
    return true;
  }

  onCancel(): void {
    this.router.navigate(['/trips']);
  }

  resetForm(): void {
    if (this.originalTrip) {
      this.trip = { ...this.originalTrip };
      this.error = null;
      this.success = null;
    }
  }

  hasChanges(): boolean {
    if (!this.originalTrip) return false;

    return JSON.stringify(this.trip) !== JSON.stringify(this.originalTrip);
  }

  formatCode(): void {
    if (this.trip.code) {
      this.trip.code = this.trip.code.toUpperCase().replace(/[^A-Z0-9]/g, '');
    }
  }

  formatPrice(): void {
    if (this.trip.perPerson) {
      // Remove any non-numeric characters except decimal point
      let price = this.trip.perPerson.replace(/[^0-9.]/g, '');

      // Ensure only one decimal point
      const parts = price.split('.');
      if (parts.length > 2) {
        price = parts[0] + '.' + parts.slice(1).join('');
      }

      // Add dollar sign and formatting
      if (price && !isNaN(parseFloat(price))) {
        const numericPrice = parseFloat(price);
        this.trip.perPerson = `$${numericPrice.toLocaleString('en-US', {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2
        })}`;
      }
    }
  }

  previewImage(): void {
    if (this.trip.image) {
      window.open(this.trip.image, '_blank');
    }
  }
}

<div class="container mt-4">
  <div class="row justify-content-center">
    <div class="col-lg-8 col-md-10">
      <!-- Header -->
      <div class="card shadow-sm border-0 mb-4">
        <div class="card-header bg-warning text-dark">
          <h2 class="mb-0">
            <i class="fas fa-edit me-2"></i>Edit Trip
          </h2>
          <p class="mb-0 mt-1 opacity-75">Update travel package information</p>
        </div>
      </div>

      <!-- Loading State -->
      <div *ngIf="loading" class="text-center py-5">
        <div class="spinner-border text-primary" role="status" style="width: 3rem; height: 3rem;">
          <span class="visually-hidden">Loading...</span>
        </div>
        <p class="mt-3 text-muted">Loading trip details...</p>
      </div>

      <!-- Success Message -->
      <div *ngIf="success" class="alert alert-success alert-dismissible fade show" role="alert">
        <i class="fas fa-check-circle me-2"></i>{{ success }}
        <button type="button" class="btn-close" (click)="success = null"></button>
      </div>

      <!-- Error Message -->
      <div *ngIf="error" class="alert alert-danger alert-dismissible fade show" role="alert">
        <i class="fas fa-exclamation-triangle me-2"></i>{{ error }}
        <button type="button" class="btn-close" (click)="error = null"></button>
      </div>

      <!-- Edit Trip Form -->
      <div *ngIf="!loading" class="card shadow-sm border-0">
        <div class="card-body p-4">
          <!-- Changes Indicator -->
          <div *ngIf="hasChanges()" class="alert alert-info" role="alert">
            <i class="fas fa-info-circle me-2"></i>
            You have unsaved changes. Don't forget to save your updates!
          </div>

          <form (ngSubmit)="onSubmit()" #tripForm="ngForm" novalidate>
            <div class="row">
              <!-- Trip Code -->
              <div class="col-md-6 mb-3">
                <label for="code" class="form-label fw-semibold">
                  <i class="fas fa-barcode me-1"></i>Trip Code *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="code"
                  name="code"
                  [(ngModel)]="trip.code"
                  (blur)="formatCode()"
                  placeholder="e.g., GALR210214"
                  maxlength="20"
                  required>
                <div class="form-text">Unique identifier for the trip (letters and numbers only)</div>
              </div>

              <!-- Trip Name -->
              <div class="col-md-6 mb-3">
                <label for="name" class="form-label fw-semibold">
                  <i class="fas fa-map-marked-alt me-1"></i>Trip Name *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="name"
                  name="name"
                  [(ngModel)]="trip.name"
                  placeholder="e.g., Gale Reef Adventure"
                  maxlength="100"
                  required>
              </div>
            </div>

            <div class="row">
              <!-- Length -->
              <div class="col-md-6 mb-3">
                <label for="length" class="form-label fw-semibold">
                  <i class="fas fa-calendar-alt me-1"></i>Duration *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="length"
                  name="length"
                  [(ngModel)]="trip.length"
                  placeholder="e.g., 4 days / 3 nights"
                  maxlength="50"
                  required>
              </div>

              <!-- Start Date -->
              <div class="col-md-6 mb-3">
                <label for="start" class="form-label fw-semibold">
                  <i class="fas fa-calendar-check me-1"></i>Start Date *
                </label>
                <input
                  type="date"
                  class="form-control"
                  id="start"
                  name="start"
                  [(ngModel)]="trip.start"
                  required>
              </div>
            </div>

            <div class="row">
              <!-- Resort -->
              <div class="col-md-6 mb-3">
                <label for="resort" class="form-label fw-semibold">
                  <i class="fas fa-hotel me-1"></i>Resort/Accommodation *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="resort"
                  name="resort"
                  [(ngModel)]="trip.resort"
                  placeholder="e.g., Emerald Bay, 3 stars"
                  maxlength="100"
                  required>
              </div>

              <!-- Price Per Person -->
              <div class="col-md-6 mb-3">
                <label for="perPerson" class="form-label fw-semibold">
                  <i class="fas fa-dollar-sign me-1"></i>Price Per Person *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="perPerson"
                  name="perPerson"
                  [(ngModel)]="trip.perPerson"
                  (blur)="formatPrice()"
                  placeholder="e.g., $1,269.00"
                  maxlength="20"
                  required>
              </div>
            </div>

            <!-- Image URL -->
            <div class="mb-3">
              <label for="image" class="form-label fw-semibold">
                <i class="fas fa-image me-1"></i>Image URL *
              </label>
              <div class="input-group">
                <input
                  type="url"
                  class="form-control"
                  id="image"
                  name="image"
                  [(ngModel)]="trip.image"
                  placeholder="https://example.com/image.jpg"
                  required>
                <button
                  type="button"
                  class="btn btn-outline-secondary"
                  (click)="previewImage()"
                  [disabled]="!trip.image"
                  title="Preview Image">
                  <i class="fas fa-eye"></i>
                </button>
              </div>
              <div class="form-text">URL to the trip's main image</div>
            </div>

            <!-- Description -->
            <div class="mb-4">
              <label for="description" class="form-label fw-semibold">
                <i class="fas fa-align-left me-1"></i>Description *
              </label>
              <textarea
                class="form-control"
                id="description"
                name="description"
                [(ngModel)]="trip.description"
                rows="4"
                placeholder="Describe the trip experience, activities, and highlights..."
                maxlength="1000"
                required></textarea>
              <div class="form-text">{{ trip.description?.length || 0 }}/1000 characters</div>
            </div>

            <!-- Form Actions -->
            <div class="d-flex gap-3 justify-content-end">
              <button
                type="button"
                class="btn btn-outline-secondary"
                (click)="onCancel()"
                [disabled]="saving">
                <i class="fas fa-times me-2"></i>Cancel
              </button>

              <button
                type="button"
                class="btn btn-outline-warning"
                (click)="resetForm()"
                [disabled]="saving || !hasChanges()">
                <i class="fas fa-undo me-2"></i>Reset Changes
              </button>

              <button
                type="submit"
                class="btn btn-warning"
                [disabled]="saving || !tripForm.form.valid || !hasChanges()">
                <span *ngIf="saving" class="spinner-border spinner-border-sm me-2"></span>
                <i *ngIf="!saving" class="fas fa-save me-2"></i>
                {{ saving ? 'Updating...' : 'Update Trip' }}
              </button>
            </div>
          </form>
        </div>
      </div>

      <!-- Form Help -->
      <div class="card bg-light border-0 mt-4" *ngIf="!loading">
        <div class="card-body">
          <h6 class="card-title">
            <i class="fas fa-lightbulb me-2"></i>Editing Tips
          </h6>
          <ul class="mb-0 small">
            <li>All fields marked with * are required</li>
            <li>Trip codes should remain unique - check for conflicts before saving</li>
            <li>Use the preview button to verify your image URL works correctly</li>
            <li>Price formatting will be applied automatically when you leave the field</li>
            <li>Changes are highlighted and must be saved to take effect</li>
            <li>Use "Reset Changes" to revert to the original values</li>
          </ul>
        </div>
      </div>
    </div>
  </div>
</div>
